//! Twirl fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for (w,h) in [(1,7),(7,1),(6,4),(18,10)] {for angle in [-45.0,50.0,720.0] {for radius in [0.0,30.0,100.0] {for center in [None,Some([0.0,0.0]),Some([2.123456789,1.75]),Some([-2.0,3.0]),Some([f64::NAN,1.75]),Some([2.123456789,f64::NAN])] {
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let input:Vec<[f32;4]>=rgba.chunks_exact(4).map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1] as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2] as f32/255.0)*a,a]}).collect();
  let mut image=Image{w,h,px:input.iter().flatten().copied().collect()};
  let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="twirl").unwrap().instance();
  effect.params.insert("angle".into(),Param::new(ParamValue::Float(angle)));
  effect.params.insert("radius".into(),Param::new(ParamValue::Float(radius)));
  if let Some([x,y])=center {effect.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(x,y))));}
  let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
  apply(&mut image,&effect,&cx);
  cases.push(json!({"parameters":{"angle":angle,"radius":radius,"center":center},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}
 let mut media=vec![];
 for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,128]}).collect();
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let local=(tick+index*100000).min(500000);let progress=local as f64/500000.0;
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut image=Image{w:16,h:16,px};
   let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="twirl").unwrap().instance();
   effect.params.insert("angle".into(),Param::new(ParamValue::Float(-45.0+progress*765.0)));
   effect.params.insert("radius".into(),Param::new(ParamValue::Float(30.0+progress*70.0)));
   effect.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(8.0-progress*6.0,8.0-progress*6.25))));
   let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.0,seconds:local as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut image,&effect,&cx);frames.push(image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
 }
 let mut image=Image{w:160,h:90,px:(0..160*90).flat_map(|_|[0.25,0.5,0.75,1.0]).collect()};
 let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="twirl").unwrap().instance();
 effect.params.insert("angle".into(),Param::new(ParamValue::Float(720.0)));
 effect.params.insert("radius".into(),Param::new(ParamValue::Float(100.0)));
 effect.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(2.123456789,1.75))));
 let cx=FxCtx{t:filmcraft_time::Tick(500000),px_scale:1.0,seconds:0.5,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
 apply(&mut image,&effect,&cx);
 let browser:Vec<u8>=image.px.chunks_exact(4).flat_map(|p|{let alpha=(p[3]*255.0+1e-4).round().clamp(0.0,255.0);let rgb:Vec<u8>=(0..3).map(|c|{if p[3]<=1e-6 {0}else{let byte=(filmcraft_color::linear_to_srgb((p[c]/p[3]).max(0.0))*255.0+1e-4).round().clamp(0.0,255.0);(byte*alpha/255.0).round() as u8}}).collect();[rgb[0],rgb[1],rgb[2],255]}).collect();
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"browser":browser,"media":media}));
}
